import {STAGES,MOVES,CHARACTERS,ACHIEVEMENTS,DEFAULT_KEYS} from './data.js';
import {Fight} from './engine.js';
import {Renderer} from './render.js';
import {AudioManager} from './audio.js';
import {load,save} from './storage.js';
import {recordMatch} from './progression.js';
import {OnlineSession,normalizeCode} from './online.js';
import {playWedding,shouldPlayWedding} from './wedding.js';
const $=s=>document.querySelector(s),overlay=$('#overlay'),renderer=new Renderer($('#game'));
const profile=load(),audio=new AudioManager(profile.settings);
let screen='loading',mode='story',selected=0,stage=0,fight=null,paused=false,returnTo='menu',campaignScore=0,bindTarget=null,toastTimer=null,settingsReturn='menu';
let online=null;
const keys=new Set(),touch=[{},{}],pending=[{},{}],chord=[false,false],edge=[{},{}];
function persist(){if(!save(profile))toast('Storage unavailable — progress lasts for this session.');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700);}
function sound(){audio.start();audio.fx('menu');}
function applySettings(){document.body.classList.toggle('no-crt',!profile.settings.crt);$('#sound').textContent=profile.settings.muted?'SOUND OFF':'SOUND ON';renderer.settings=profile.settings;}
function clearInput(){keys.clear();touch[0]={};touch[1]={};pending[0]={};pending[1]={};edge[0]={};edge[1]={};chord[0]=chord[1]=false;}
function show(name,html){screen=name;overlay.innerHTML=html;document.body.classList.toggle('playing',name==='fight');$('#pause').hidden=name!=='fight';clearInput();if(name!=='fight')overlay.querySelector('button')?.focus({preventScroll:true});}
function btn(action,label,cls='',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function panel(title,body,back='menu'){return `<section class="panel-screen"><header class="panel-top"><h1 class="screen-title">${title}</h1>${btn(back,'← BACK','back')}</header>${body}</section>`;}
function title(){fight=null;stage=3;show('title',`<section class="title-screen"><div class="eyebrow">A TWO-PLAYER LOVE STORY</div><h1 class="game-logo">LOVE<span>FIGHT</span></h1><div class="subtitle">THE PDA ARCADE</div><p class="title-copy">Steal a kiss. Start a rivalry.<br>Fall in love all over again.</p><div class="anniversary-card"><span class="anniversary-heart">♥</span><p class="anniversary-heading">Happy 5th Anniversary Zihan!</p><p class="anniversary-message">PRAY you become a better person and treat me with love and respect; HOW you intend to!</p></div>${btn('menu','PRESS START','start-button')}<div class="title-meta"><span class="coin">INSERT COIN? <b>JUST YOUR HEART.</b></span><span>HI-SCORE <b>${String(profile.highScore).padStart(6,'0')}</b></span></div><div class="screen-stamp">MAHERA × ZIHAN<br>8 ARENAS · 1 FOREVER</div></section>`);}
function menu(){leaveOnline();$('#footer-hint').textContent='ENTER TO CHOOSE · TWO HEARTS. TWO BUTTONS.';fight=null;paused=false;stage=0;audio.active=true;show('menu',`<section class="menu-screen"><p class="screen-kicker">MAHERA × ZIHAN · INSERT AFFECTION</p><h1 class="screen-title">CHOOSE YOUR CHAOS.</h1><nav class="menu-list" aria-label="Game modes">${[['quick','PLAY / QUICK MATCH'],['story','STORY MODE'],['versus','VERSUS MODE'],['training','TRAINING MODE'],['arcade','ARCADE MODE'],['characters','CHARACTER SELECT'],['stats','RELATIONSHIP STATS'],['settings','SETTINGS']].map(([a,l],i)=>btn(a,`<span>${String(i+1).padStart(2,'0')}</span>${l}`)).join('')}</nav><div class="menu-note">LOVE IS A CONTACT SPORT.<br>SOLO, LOCAL VERSUS OR ONLINE TWO PLAYER.</div><div class="screen-stamp">NO HARD FEELINGS.<br>ONLY HEART FEELINGS.</div></section>`);}
function chooseMode(m){mode=m;campaignScore=0;returnTo='menu';characterSelect();}
function characterSelect(){let cards=CHARACTERS.map((ch,i)=>`<button class="character ${selected===i?'selected':''}" data-action="select-character" data-id="${i}" aria-pressed="${selected===i}"><img class="portrait" src="${renderer.portrait(i)}" alt="${ch.name} pixel fighter"><div><span class="tag">${selected===i?'♥ PLAYER 1':mode==='versus'?'PLAYER 2':'PARTNER / CPU'}</span><h3>${ch.name}</h3><span class="tag">${ch.title}</span><p>${ch.description}</p>${[['POWER',ch.power],['SPEED',ch.speed],['DEFENSE',ch.defense],['CUTENESS',ch.cuteness]].map(([name,value])=>`<div class="attribute"><span>${name}</span>${Array.from({length:5},(_,k)=>`<i class="pip ${k>=value?'off':''}"></i>`).join('')}</div>`).join('')}</div></button>`).join('');show('characters',panel('PICK YOUR HEARTBREAKER.',`<p class="screen-kicker">${mode.toUpperCase()} · TWO HEARTS, VERY DIFFERENT TACTICS</p><div class="characters">${cards}</div><div class="select-bottom"><p>P1: ${CHARACTERS[selected].name} &nbsp; / &nbsp; ${mode==='versus'?'P2':'CPU'}: ${CHARACTERS[1-selected].name}<br>${mode==='versus'?'Two players share one keyboard. Choosing P1 assigns the other partner to P2.':'Your partner changes outfits and tactics with every arena.'}</p>${btn('choose-stage','CHOOSE ARENA →','primary')}</div>`));}
function chooseStage(){if(mode==='arcade'){stage=0;storyIntro();return;}let cards=STAGES.map((s,i)=>{let locked=mode==='story'&&i>profile.unlocked;return `<button class="stage-card" data-action="stage" data-id="${i}" ${locked?'disabled':''}><div class="stage-thumb" style="background-position:${i%4*100/3}% ${Math.floor(i/4)*100}%"></div><em>${locked?'LOCKED':String(i+1).padStart(2,'0')}</em><b>${s.name}</b><small>${s.location} · ${i===4?'Usable bed':s.prop.name.toLowerCase()}</small></button>`;}).join('');show('stages',panel('EIGHT PLACES. ZERO PERSONAL SPACE.',`<p class="screen-kicker">${mode==='story'?'WIN TO CONTINUE YOUR STORY':'ALL ARENAS OPEN · BEST OF THREE'}</p><div class="stages">${cards}</div><div class="select-bottom"><p>Furniture is part of the fight. Jump onto platforms or press USE nearby.<br>Stage moves change; your two attack buttons stay the same.</p>${btn('guide','CONTROLS','secondary')}</div>`,'characters'));}
function storyIntro(){fight=null;const s=STAGES[stage];audio.theme=stage;show('intro',`<section class="dialog-screen"><article class="dialog-box"><p class="screen-kicker">${mode.toUpperCase()} · CHAPTER ${String(stage+1).padStart(2,'0')} OF 08</p><h2>${s.name} — ${s.location}</h2><p>${s.dialog.join('<br>')}</p><footer><small>${s.challenge}</small>${btn('start-fight','LET’S DO THIS ♥','primary')}</footer></article></section>`);}
function startFight(){paused=false;audio.active=true;audio.theme=stage;fight=new Fight({stage,character:selected,mode,difficulty:profile.settings.difficulty,onEvent:onFightEvent});if(mode==='training'){fight.countdown=0;fight.bannerTime=0;fight.fighters.forEach(p=>p.energy=100);}showFight();$('#footer-hint').textContent=profile.settings.keys.map((map,i)=>`P${i+1}: ${prettyKey(map.kiss)} / ${prettyKey(map.hug)} ATTACK · ${prettyKey(map.interact)} USE`).join(' | ');
}
function showFight(){show('fight',mode==='training'?`<div class="train-info" id="train-info">TRAINING · NO TIME LIMIT<br>KISS + HUG = SPECIAL<br>USE FURNITURE / E</div><div class="training-toolbar">${btn('dummy','DUMMY: '+fight.trainingAI.toUpperCase())}${btn('refill','REFILL')}${btn('guide','MOVE LIST')}${btn('training-stages','ARENAS')}</div>`:'');}
function onFightEvent(e){if(e.type==='attack')audio.fx(e.id);if(['block','jump','dodge','interact','round'].includes(e.type))audio.fx(e.type);if(e.type==='hit')audio.fx(e.id==='overload'?e.phase:'hit');if(e.type==='hint')toast(e.text);if(e.type==='start')audio.fx('round');if(e.type==='end'){finishMatch(e.winner);if(shouldPlayWedding(mode,stage,e.winner))playWedding(overlay,{onSound:id=>audio.fx(id)});}}
function finishMatch(winner){if(mode==='online')return onlineFinish(winner);paused=false;audio.fx('victory');let p=fight.fighters[0];const result=recordMatch(profile,fight,winner,mode,stage,campaignScore);campaignScore=result.campaignScore;const {earned,won}=result;persist();if(earned.length){toast(`ACHIEVEMENT: ${earned.map(x=>x[1]).join(' + ')}`);audio.fx('achievement');}const continueRun=won&&['story','arcade'].includes(mode)&&stage<7;show('victory',`<section class="victory"><p class="screen-kicker">${stage===7&&won&&mode==='story'?'THE END? NEVER.':mode==='versus'?`PLAYER ${winner+1} WINS`:won?'LOVE WINS. SO DO YOU.':'ONE MORE KISS?'}</p><h1 class="win-banner"><span>♥</span> ${won||mode==='versus'?'YOU WIN':'LOVE WINS'} <span>♥</span></h1><p class="victory-signature">YOU HAVE BEEN DEFEATED BY LOVE.</p><p class="result">${CHARACTERS[fight.fighters[winner].character].name} · ${fight.wins[winner]}–${fight.wins[1-winner]} · ${STAGES[stage].location.toUpperCase()}</p><div class="victory-prompt"><h2>▸ CONTINUE<br>TOGETHER?</h2>${btn(continueRun?'next-stage':'rematch','♥ YES','continue-yes')}${btn('menu','NO','continue-no')}</div><div class="summary"><div><small>LOVE SCORE</small>${String(campaignScore).padStart(6,'0')}</div><div><small>BEST COMBO</small>${Math.max(...fight.fighters.map(p=>p.maxCombo))} HITS</div><div><small>KISSES / HUGS</small>${p.kisses} / ${p.hugs}</div><div><small>FOREVER STATUS</small>${stage===7&&won?'TO BE CONTINUED ♥':'STILL VERY TAKEN'}</div></div><div class="modal-actions">${btn('choose-stage',mode==='arcade'?'NEW ARCADE RUN':'CHANGE ARENA','secondary')}${btn('stats','RELATIONSHIP STATS','secondary')}</div></section>`);}
function leaveOnline(){online?.close();online=null;$('#network-status').hidden=true;}
function versusOptions(){show('versus-options',panel('TWO PLAYERS. ONE LOVE FIGHT.',`<div class="versus-options"><article><h2>ON THE SAME COUCH</h2><p>Two players. One computer.<br>Separate keys on one keyboard.</p>${btn('local-versus','LOCAL TWO PLAYER','primary')}</article><article><h2>HEARTS, CONNECTED</h2><p>Two computers. One private room.<br>Live movement, moves and rematches.</p>${btn('online','ONLINE TWO PLAYER','primary')}</article></div><p class="online-note">Desktop edition · Both players control a real fighter · Two attack buttons each</p>`));}
function onlineEntry(message=''){
 leaveOnline();fight=null;mode='online';paused=false;
 const invite=new URLSearchParams(location.search).get('room')||'';
 const code=normalizeCode(invite).replace(/[^A-Z2-9]/g,'').slice(0,8);
 show('online',panel('LOVE HAS NO DISTANCE.',`<p class="screen-kicker">ONLINE TWO PLAYER · PRIVATE ROOM</p><div class="versus-options"><article><h2>HOST A DATE</h2><p>Create a room, choose your arena<br>and invite your player two.</p>${btn('host-room','CREATE ROOM','primary')}</article><article><h2>JOIN YOUR PARTNER</h2><label class="room-label" for="room-code">ROOM CODE</label><input id="room-code" class="room-input" maxlength="12" autocomplete="off" spellcheck="false" placeholder="ABCD EFGH" value="${code}">${btn('join-room','JOIN ROOM','primary')}</article></div><p id="online-message" class="online-note" role="status"></p><p class="online-note">Both players use their own P1 keys: WASD · F / G · E to use furniture.<br>Keep both game tabs open. An internet connection is required.</p>`,'versus-options'));
 $('#online-message').textContent=message;
}
function connectOnline(role){
 const code=$('#room-code')?.value||'';
 online=new OnlineSession({
  status:message=>{const el=$('#online-message');if(el)el.textContent=message;if(online?.fight)$('#network-status').textContent=message;},
  lobby:onlineLobby,
  latency:ms=>{if(online?.fight)$('#network-status').textContent=`ONLINE · YOU ARE P${online.host?1:2} · ${ms} MS${ms>180?' · HIGH LATENCY':''}`;},
  match:newFight=>{fight=newFight;stage=online.config.stage;selected=online.config.character;paused=false;mode='online';audio.active=true;audio.theme=stage;showFight();$('#network-status').hidden=false;$('#network-status').textContent=`ONLINE · YOU ARE P${online.host?1:2}`;const map=profile.settings.keys[0];$('#footer-hint').textContent=`YOU: ${CHARACTERS[fight.fighters[online.host?0:1].character].name} · ${prettyKey(map.kiss)} / ${prettyKey(map.hug)} ATTACK · ${prettyKey(map.interact)} USE`;},
  event:onFightEvent,
  pause:value=>{paused=value;clearInput();audio.active=!value;if(value){show('pause',`<section class="modal-screen"><div class="modal"><p class="screen-kicker">ONLINE · BOTH PLAYERS PAUSED</p><h2>HOLD THAT KISS.</h2><p>One of you paused or switched tabs.<br>Resume when both players are ready.</p><div class="modal-actions">${btn('resume','RESUME TOGETHER','primary')}${btn('menu','LEAVE ROOM','secondary')}</div></div></section>`);}else showFight();},
  votes:()=>{const el=$('[data-action="online-rematch"]');if(el){const own=online.host?0:1;el.disabled=online.votes[own];el.textContent=online.votes[own]?'WAITING FOR PARTNER…':online.votes[1-own]?'♥ PARTNER SAYS YES — REMATCH?':'♥ YES';}},
  error:message=>{paused=true;onlineEntry(message);}
 });
 show('online-connecting',panel('CONNECTING TWO HEARTS.',`<div class="online-connection"><p id="online-message" role="status">Opening a private room…</p><p>Both players need the same version of the game.</p></div>`,'online'));
 online.open(role,code,{stage:0,character:selected});
}
function onlineLobby(){
 if(!online||online.closed)return;
 stage=online.config.stage;selected=online.config.character;
 const own=online.host?0:1,who=CHARACTERS[own?1-selected:selected];
 const controls=online.host?`<label>YOUR FIGHTER<select id="online-character">${CHARACTERS.map((ch,i)=>`<option value="${i}" ${i===selected?'selected':''}>${ch.name}</option>`).join('')}</select></label><label>ARENA<select id="online-stage">${STAGES.map((s,i)=>`<option value="${i}" ${i===stage?'selected':''}>${String(i+1).padStart(2,'0')} · ${s.name}</option>`).join('')}</select></label>`:`<div class="guest-assignment"><h2>YOU ARE ${who.name}</h2><p>${STAGES[stage].name}<br>${STAGES[stage].location}</p><p>The host chooses the arena.<br>Ready up when you’re set.</p></div>`;
 show('online-lobby',panel('YOUR PLAYER TWO IS OUT THERE.',`<p class="screen-kicker">${online.host?'HOST · PLAYER 1':'GUEST · PLAYER 2'} · ${who.name}</p><div class="lobby-grid"><article class="room-card"><span>ROOM CODE</span><output id="room-display">${online.code}</output>${btn('copy-code','COPY CODE','secondary')}${btn('copy-invite','COPY INVITE LINK','secondary')}<p id="online-message" role="status">${online.connected?'♥ TWO HEARTS CONNECTED':'Waiting for your partner to join…'}</p><small>Share the code privately with your partner.</small></article><article class="lobby-settings">${controls}<p id="ready-status">${online.connected?online.ready?'PLAYER 2 IS READY ♥':'PLAYER 2 IS GETTING READY':'PLAYER 2 NOT CONNECTED'}</p>${online.host?btn('online-start','START TOGETHER','primary',online.connected&&online.ready?'':'disabled'):btn('online-ready',online.ready?'CANCEL READY':'I’M READY ♥','primary')}</article></div><p class="online-note">WASD move · F / G attacks · F + G special · E furniture · ESC pauses both players</p>`,'online'));
}
async function copyInvite(codeOnly){
 if(!online)return;
 if(!codeOnly&&['localhost','127.0.0.1'].includes(location.hostname)){toast('This is a local address. Share the room code; your partner must open their own copy of the game.');return;}
 const url=new URL(location.href);url.search='';url.hash='';url.searchParams.set('room',online.code);
 try{await navigator.clipboard.writeText(codeOnly?online.code:url.href);toast(codeOnly?'Room code copied.':'Invite link copied.');}catch{toast(`Copy this room code: ${online.code}`);}
}
function onlineFinish(winner){
 const own=online.host?0:1,won=winner===own,p=fight.fighters[own];
 const localView={...fight,fighters:own?[fight.fighters[1],fight.fighters[0]]:fight.fighters};
 recordMatch(profile,localView,won?0:1,'versus',stage,0);persist();audio.fx('victory');
 show('victory',`<section class="victory"><p class="screen-kicker">ONLINE · ${CHARACTERS[fight.fighters[winner].character].name} WINS</p><h1 class="win-banner"><span>♥</span> ${won?'YOU WIN':'LOVE WINS'} <span>♥</span></h1><p class="victory-signature">YOU HAVE BEEN DEFEATED BY LOVE.</p><p class="result">${fight.wins[0]}–${fight.wins[1]} · ${STAGES[stage].location.toUpperCase()}</p><div class="victory-prompt"><h2>▸ CONTINUE<br>TOGETHER?</h2>${btn('online-rematch','♥ YES','continue-yes')}${btn('menu','NO','continue-no')}</div><div class="summary"><div><small>LOVE SCORE</small>${String(fight.score).padStart(6,'0')}</div><div><small>YOUR BEST COMBO</small>${p.maxCombo} HITS</div><div><small>YOUR KISSES / HUGS</small>${p.kisses} / ${p.hugs}</div><div><small>REMATCH</small>BOTH SAY YES ♥</div></div></section>`);
}

function pause(){if(screen!=='fight')return;if(mode==='online'){online?.setPause(true);return;}paused=true;audio.active=false;show('pause',`<section class="modal-screen"><div class="modal"><p class="screen-kicker">EVEN ROMANCE NEEDS A BREATHER</p><h2>HOLD THAT KISS.</h2><p>The timer is paused. Your partner can wait.<br>${STAGES[stage].challenge}</p><div class="modal-actions">${btn('resume','KEEP FLIRTING','primary')}${btn('guide','CONTROLS & MOVES','secondary')}${btn('settings','SETTINGS','secondary')}${btn('restart','RESTART MATCH','secondary')}${btn('menu','MAIN MENU','secondary')}</div></div></section>`);}
function resume(){if(mode==='online'){online?.setPause(false);return;}paused=false;audio.active=true;showFight();}
function guide(){returnTo=screen;const s=STAGES[stage],labels={left:'Move left',right:'Move right',jump:'Jump',down:'Crouch',kiss:'Kiss',hug:'Hug',dodge:'Dodge',interact:'Use furniture'};const sections=profile.settings.keys.map((map,i)=>`<div><h3>PLAYER ${i+1}</h3>${Object.entries(map).map(([action,key])=>`<p><kbd>${prettyKey(key)}</kbd> — ${labels[action]}</p>`).join('')}</div>`).join('');if(fight)paused=true;show('guide',panel('TWO BUTTONS. MANY BAD IDEAS.',`<div class="guide">${sections}</div><p style="font-size:10px;line-height:1.8;color:#dcc0d4">Hold away from your partner to BLOCK. Double-tap a direction to RUN. DODGE grants a brief invulnerable sidestep. Press KISS + HUG together for your stage special (40 energy), or PDA OVERLOAD at 100. Grabs beat blocks. Jump onto furniture or press USE nearby to sit, charge energy, and perform a contextual PDA move.</p><table class="move-table"><thead><tr><th>${s.location.toUpperCase()}</th><th>INPUT</th><th>DAMAGE / RANGE</th></tr></thead><tbody>${[...s.moves,s.special,'overload'].map((id,i)=>`<tr><td>${MOVES[id].name}</td><td>${i===0?'KISS':i===1?'HUG':i===2?'BOTH · 40 ENERGY':'BOTH · 100 ENERGY'}</td><td>${MOVES[id].damage} × ${MOVES[id].hits} / ${MOVES[id].range}</td></tr>`).join('')}</tbody></table>`,'close-guide'));}
function closeGuide(){if(returnTo==='fight')resume();else if(returnTo==='pause'){screen='fight';pause();}else chooseStage();}
function stats(){const stats=[['LOVE POINTS',profile.love],['AFFECTION POINTS',profile.affection],['PDA SCORE',profile.score],['COMBO RECORD',profile.combo+' HITS'],['TOTAL KISSES',profile.kisses],['TOTAL HUGS',profile.hugs],['VICTORIES',profile.wins],['SPECIALS UNLOCKED',new Set(['overload',...STAGES.slice(0,profile.unlocked+1).map(s=>s.special)]).size+' / 6']];show('stats',panel('OUR VERY COMPETITIVE LOVE STORY.',`<p class="screen-kicker">SAVED ON THIS DEVICE · ${profile.unlocked+1}/8 STORY ARENAS UNLOCKED</p><div class="stats-grid">${stats.map(([label,value])=>`<div class="stat"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><div class="badges">${ACHIEVEMENTS.map(([id,name,desc,,icon])=>`<div class="badge ${profile.badges.includes(id)?'earned':''}"><i>${icon}</i><div>${name}<small>${desc}</small></div></div>`).join('')}</div>`));}
function prettyKey(key){return key.replace('Key','').replace('Digit','').replace('Arrow','').replace('Space','SPACE');}
function settings(){if(screen!=='settings')settingsReturn=screen;show('settings',panel('SET THE MOOD.',`<div class="settings-grid"><div class="setting-box"><h3>SOUND & FEEL</h3><label class="setting-row">MUSIC<input data-setting="music" type="range" min="0" max="1" step="0.05" value="${profile.settings.music}" aria-label="Music volume"></label><label class="setting-row">SOUND EFFECTS<input data-setting="sfx" type="range" min="0" max="1" step="0.05" value="${profile.settings.sfx}" aria-label="Sound effects volume"></label><label class="setting-row">CRT SCANLINES<input data-setting="crt" type="checkbox" ${profile.settings.crt?'checked':''}></label><label class="setting-row">SCREEN SHAKE<input data-setting="shake" type="checkbox" ${profile.settings.shake?'checked':''}></label><label class="setting-row">CPU DIFFICULTY<select data-setting="difficulty"><option value="easy" ${profile.settings.difficulty==='easy'?'selected':''}>SWEET</option><option value="normal" ${profile.settings.difficulty==='normal'?'selected':''}>FLIRTY</option><option value="hard" ${profile.settings.difficulty==='hard'?'selected':''}>RELENTLESS</option></select></label><p style="font-size:9px;line-height:1.7;color:#bd9cb7">Original synthesized chiptunes and effects.<br>Audio begins after your first interaction.<br>Difficulty applies to the next match.</p></div><div class="setting-box"><h3>REMAP YOUR KEYBOARD</h3><p style="font-size:9px;color:#bfa2b8">Click a binding, then press a new key. ESC cancels.</p><div class="bindings">${profile.settings.keys.map((map,i)=>Object.entries(map).map(([act,key])=>btn('bind',`P${i+1} ${act.toUpperCase()} : ${prettyKey(key)}`,'binding',`data-player="${i}" data-key="${act}"`)).join('')).join('')}</div><div style="margin-top:12px">${btn('default-keys','RESTORE DEFAULT KEYS','secondary')}</div></div></div>`,'close-settings'));}
function closeSettings(){bindTarget=null;if(settingsReturn==='pause'){screen='fight';pause();}else menu();}
overlay.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;sound();dispatch(b.dataset.action,b.dataset);});
function dispatch(action,data={}){switch(action){case'menu':menu();break;case'quick':chooseMode('quick');break;case'versus':case'versus-options':versusOptions();break;case'local-versus':chooseMode('versus');break;case'online':onlineEntry();break;case'host-room':connectOnline('host');break;case'join-room':connectOnline('guest');break;case'copy-code':copyInvite(true);break;case'copy-invite':copyInvite(false);break;case'online-ready':online?.setReady();break;case'online-start':online?.start();break;case'online-rematch':online?.requestRematch();break;case'story':case'training':case'arcade':chooseMode(action);break;case'characters':characterSelect();break;case'select-character':selected=Number(data.id);characterSelect();break;case'choose-stage':chooseStage();break;case'stage':stage=Number(data.id);if(mode==='story'&&stage>profile.unlocked)return;if(['story','arcade'].includes(mode))storyIntro();else startFight();break;case'start-fight':case'restart':case'rematch':startFight();break;case'next-stage':stage++;storyIntro();break;case'stats':stats();break;case'settings':settings();break;case'close-settings':closeSettings();break;case'guide':guide();break;case'close-guide':closeGuide();break;case'resume':resume();break;case'dummy':fight.trainingAI=['idle','block','fight'][(['idle','block','fight'].indexOf(fight.trainingAI)+1)%3];showFight();break;case'refill':fight.resetTraining();break;case'training-stages':fight=null;chooseStage();break;case'bind':bindTarget={player:Number(data.player),action:data.key};toast('Press a new key. Escape cancels.');break;case'default-keys':profile.settings.keys=structuredClone(DEFAULT_KEYS);persist();settings();break;}}
overlay.addEventListener('change',e=>{if(['online-character','online-stage'].includes(e.target.id))online?.configure({character:Number($('#online-character').value),stage:Number($('#online-stage').value)});});
overlay.addEventListener('input',e=>{const el=e.target,k=el.dataset.setting;if(!k)return;profile.settings[k]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;persist();applySettings();});
function mapped(player,action){return keys.has(profile.settings.keys[player][action])||touch[player][action];}
function readInputs(now){return[0,1].map(i=>{let input={left:!!mapped(i,'left'),right:!!mapped(i,'right'),down:!!mapped(i,'down')};for(const a of ['jump','dodge','interact']){input[a]=!!edge[i][a];delete edge[i][a];}const both=mapped(i,'kiss')&&mapped(i,'hug');if(both&&!chord[i]){input.special=true;chord[i]=true;pending[i]={};}else if(!both){if(!mapped(i,'kiss')&&!mapped(i,'hug'))chord[i]=false;for(const a of ['kiss','hug'])if(pending[i][a]&&now-pending[i][a]>=75){input[a]=true;delete pending[i][a];}}return input;});}
function pressAction(i,act){if(['kiss','hug'].includes(act))pending[i][act]=performance.now();else edge[i][act]=true;}
document.addEventListener('keydown',e=>{if(bindTarget){e.preventDefault();if(e.code==='Escape'){bindTarget=null;toast('Key change cancelled.');return;}if(['Tab','MetaLeft','MetaRight','ControlLeft','ControlRight'].includes(e.code))return;const conflict=profile.settings.keys.some((map,i)=>Object.entries(map).some(([action,code])=>code===e.code&&(i!==bindTarget.player||action!==bindTarget.action)));if(conflict){toast('That key is already assigned. Choose another.');return;}profile.settings.keys[bindTarget.player][bindTarget.action]=e.code;bindTarget=null;persist();settings();return;}
 if(e.code==='Escape'){e.preventDefault();if(screen==='fight')pause();else if(screen==='pause')resume();else if(screen==='guide')closeGuide();else if(screen==='settings')closeSettings();else menu();return;}
 if(screen==='title'&&['Enter','Space'].includes(e.code)){e.preventDefault();sound();menu();return;}
 if(screen!=='fight'){if(['ArrowDown','ArrowUp'].includes(e.code)&&!['INPUT','SELECT'].includes(e.target.tagName)){e.preventDefault();const all=[...overlay.querySelectorAll('button:not(:disabled)')],idx=all.indexOf(document.activeElement);all[(idx+(e.code==='ArrowDown'?1:-1)+all.length)%all.length]?.focus();}return;}
 if(e.repeat)return;for(let i=0;i<2;i++){for(const [act,code]of Object.entries(profile.settings.keys[i]))if(code===e.code){e.preventDefault();pressAction(i,act);}}keys.add(e.code);audio.start();});
document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(screen==='fight'&&mode!=='online')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='fight'){clearInput();pause();}});
for(const b of document.querySelectorAll('[data-input]')){b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch[0][b.dataset.input]=true;pressAction(0,b.dataset.input);audio.start();});const release=e=>{e.preventDefault();touch[0][b.dataset.input]=false;};b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release);}
$('#pause').onclick=pause;$('#home').onclick=e=>{e.preventDefault();sound();menu();};$('#sound').onclick=()=>{audio.start();profile.settings.muted=!profile.settings.muted;persist();applySettings();};$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await $('.cabinet').requestFullscreen();else await document.exitFullscreen();}catch{toast('Use your browser’s full-screen control.');}};
applySettings();show('loading',`<section class="modal-screen"><div class="modal"><h2>LOADING AFFECTION…</h2><p>Warming up eight arenas and two hearts.</p></div></section>`);await renderer.load();if(new URLSearchParams(location.search).has('room'))onlineEntry();else title();
let last=performance.now(),trainTick=0;function loop(now){const dt=Math.min((now-last)/1000,.0334);last=now;audio.tick();if(online&&!online.closed)online.tick(dt,screen==='fight'&&!paused?readInputs(now)[0]:{},now);if(mode!=='online'&&screen==='fight'&&!paused&&fight){fight.step(dt,readInputs(now));if(mode==='training'&&now-trainTick>150){trainTick=now;let p=fight.fighters[0],el=$('#train-info');if(el)el.innerHTML=`TRAINING · ${fight.trainingAI.toUpperCase()} DUMMY<br>${p.lastMove||'TRY A KISS OR HUG'} · ${p.lastDamage} DAMAGE<br>COMBO ${p.combo} · RECORD ${p.maxCombo}<br>${p.onPlatform?'ON '+STAGES[stage].prop.name:'JUMP / USE FURNITURE'}`;}}
 if(fight){$('#combat-status').textContent=`${screen} | ${mode} | ${STAGES[stage].location} | Round ${fight.round} | Score ${fight.wins.join('-')} | `+fight.fighters.map(p=>`${CHARACTERS[p.character].name}: ${Math.round(p.hp)} composure, ${Math.floor(p.energy)} energy, ${p.combo} combo, ${p.onPlatform?'on furniture':'floor'}, ${p.lastMove||'ready'}`).join(' | ');}const isFight=['fight','pause','guide','settings'].includes(screen)&&fight;renderer.render(isFight?fight:null,{stage,menu:['title','menu','characters','stages','settings','stats'].includes(screen),victory:screen==='victory',victoryCharacter:fight?.fighters[fight?.roundWinner]?.character||0});requestAnimationFrame(loop);}requestAnimationFrame(loop);
// Deliberately read-only diagnostics for local QA and browser inspection.
window.loveFight={get state(){return{screen,mode,stage,selected,paused,fight:fight?{timer:fight.timer,round:fight.round,wins:[...fight.wins],countdown:fight.countdown,players:fight.fighters.map(p=>({name:CHARACTERS[p.character].name,x:p.x,y:p.y,hp:p.hp,energy:p.energy,state:p.state,combo:p.combo,onPlatform:p.onPlatform,lastMove:p.lastMove}))}:null};}};
